"""Budgets: spending limits per calendar period and their status."""
import re
from dataclasses import dataclass
from datetime import date
from decimal import Decimal
from fractions import Fraction

from .dates import Period, is_date, last_day
from .errors import ValidationError
from .ledger import Ledger
from .money import Money, round_div

_KINDS = ("month", "quarter", "year")
_KIND_MONTHS = {"month": 1, "quarter": 3, "year": 12}
_SEG_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


class BudgetError(ValidationError):
    pass


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise BudgetError("invalid budget pattern '%s': expected account segments joined by ':'" % (pattern,))
    for seg in pattern.split(":"):
        if seg != "*" and not _SEG_RE.fullmatch(seg):
            raise BudgetError(
                "invalid budget pattern '%s': segment '%s' must be '*' or start with a capital letter"
                % (pattern, seg)
            )


@dataclass(frozen=True)
class Budget:
    pattern: str
    period_kind: str
    amount: Money
    start: date

    def __post_init__(self):
        _check_pattern(self.pattern)
        if not isinstance(self.period_kind, str) or self.period_kind not in _KINDS:
            raise BudgetError(
                "invalid period kind '%s': expected month, quarter or year" % (self.period_kind,)
            )
        if not isinstance(self.amount, Money) or self.amount.minor <= 0:
            raise BudgetError("budget amount must be money greater than zero, got '%s'" % (self.amount,))
        if not is_date(self.start):
            raise BudgetError("budget start must be a date, got '%s'" % (self.start,))


def _money_dict(m):
    return {"amount": m.amount_str(), "currency": m.currency}


@dataclass(frozen=True)
class BudgetLine:
    pattern: str
    period_kind: str
    budget: Money
    actual: Money
    remaining: Money
    percent: Decimal
    over: bool
    accounts: tuple

    def to_dict(self):
        return {
            "pattern": self.pattern,
            "period_kind": self.period_kind,
            "budget": _money_dict(self.budget),
            "actual": _money_dict(self.actual),
            "remaining": _money_dict(self.remaining),
            "percent": str(self.percent),
            "over": self.over,
            "accounts": [{"account": a, "amount": _money_dict(m)} for a, m in self.accounts],
        }


def _matches(segments, account):
    parts = account.split(":")
    if parts[0] != "Expenses" or len(parts) < len(segments):
        return False
    return all(s == "*" or s == p for s, p in zip(segments, parts))


def _index(d, months):
    return (d.year * 12 + d.month - 1) // months


def _bounds(i, months):
    first = i * months
    y, m = divmod(first, 12)
    ey, em = divmod(first + months - 1, 12)
    return date(y, m + 1, 1), date(ey, em + 1, last_day(ey, em + 1))


def _allowance(budget, period):
    months = _KIND_MONTHS[budget.period_kind]
    first = _index(budget.start, months)
    a = max(first, _index(period.start, months))
    b = _index(period.end, months)
    if first > b:
        return None
    total = Fraction(0)
    ends = {a, b}
    for i in ends:
        ps, pe = _bounds(i, months)
        lo = max(ps, period.start)
        hi = min(pe, period.end)
        total += Fraction((hi - lo).days + 1, (pe - ps).days + 1)
    total += max(0, b - a - 1)
    minor = round_div(budget.amount.minor * total.numerator, total.denominator)
    return Money(minor, budget.amount.currency)


def _percent(actual, allowance):
    if allowance.minor == 0:
        return Decimal("0.0") if actual.minor == 0 else Decimal("100.0")
    tenths = round_div(actual.minor * 1000, allowance.minor)
    if tenths == 0:
        return Decimal("0.0")
    sign = "-" if tenths < 0 else ""
    whole, frac = divmod(abs(tenths), 10)
    return Decimal("%s%d.%d" % (sign, whole, frac))


def budget_status(budgets, ledger, period):
    if isinstance(budgets, (str, bytes)) or not hasattr(budgets, "__iter__"):
        raise BudgetError("budgets must be a list of Budget")
    budgets = list(budgets)
    for b in budgets:
        if not isinstance(b, Budget):
            raise BudgetError("not a budget: '%s'" % (b,))
    if not isinstance(ledger, Ledger):
        raise BudgetError("not a ledger: '%s'" % (ledger,))
    if not isinstance(period, Period):
        raise BudgetError("not a period: '%s'" % (period,))

    spent = [
        (p.account, p.amount.currency, p.amount.minor)
        for tx, p in ledger.postings()
        if period.start <= tx.date <= period.end and p.account.split(":")[0] == "Expenses"
    ]
    entries = []
    for pos, b in enumerate(budgets):
        allowance = _allowance(b, period)
        if allowance is None:
            continue
        cur = b.amount.currency
        segments = b.pattern.split(":")
        per_account = {}
        for account, c, minor in spent:
            if c == cur and _matches(segments, account):
                per_account[account] = per_account.get(account, 0) + minor
        total = sum(per_account.values())
        actual = Money(total, cur)
        accounts = tuple((a, Money(v, cur)) for a, v in sorted(per_account.items()) if v != 0)
        line = BudgetLine(
            b.pattern,
            b.period_kind,
            allowance,
            actual,
            allowance - actual,
            _percent(actual, allowance),
            actual.minor > allowance.minor,
            accounts,
        )
        entries.append(((b.pattern, _KINDS.index(b.period_kind), b.start, pos), line))
    entries.sort(key=lambda e: e[0])
    return [line for _, line in entries]

"""Recurring transactions: schedule words, occurrence dates and dated copies."""
import re
from dataclasses import dataclass
from datetime import date
from typing import Optional

from .dates import DateError, format_date, is_date, last_day, parse_date
from .errors import ValidationError
from .model import Transaction

_MIN_ORD = date.min.toordinal()
_MAX_ORD = date.max.toordinal()
_T_MIN = date.min.year * 12
_T_MAX = date.max.year * 12 + 11

_WEEKDAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
_WEEKDAY_NAMES = (
    "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday",
)
_MONTH_NAMES = (
    "January", "February", "March", "April", "May", "June", "July",
    "August", "September", "October", "November", "December",
)
_UNITS = {
    "day": "days", "days": "days", "week": "weeks", "weeks": "weeks",
    "month": "months", "months": "months", "year": "years", "years": "years",
}
_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_NUM_RE = re.compile(r"[0-9]+")
_YMD_RE = re.compile(r"([0-9]{2})-([0-9]{2})")

_SHAPES = (
    "daily, weekly on mon|tue|wed|thu|fri|sat|sun, monthly on 1-31, monthly on last, "
    "yearly on MM-DD, every N days|weeks|months|years from YYYY-MM-DD"
)


class RecurringError(ValidationError):
    pass


def _bad(text, why=None):
    msg = "invalid schedule '%s': expected one of: %s" % (text, _SHAPES)
    if why:
        msg += " (%s)" % why
    return RecurringError(msg)


@dataclass(frozen=True)
class Schedule:
    kind: str
    weekday: Optional[int] = None
    day: Optional[int] = None  # day of month; 0 means the last day
    month: Optional[int] = None
    step: Optional[int] = None
    unit: Optional[str] = None  # always plural
    anchor: Optional[date] = None

    def __str__(self):
        k = self.kind
        if k == "daily":
            return "daily"
        if k == "weekly":
            return "weekly on %s" % _WEEKDAYS[self.weekday]
        if k == "monthly":
            return "monthly on %s" % ("last" if self.day == 0 else self.day)
        if k == "yearly":
            return "yearly on %02d-%02d" % (self.month, self.day)
        unit = self.unit[:-1] if self.step == 1 else self.unit
        return "every %d %s from %s" % (self.step, unit, format_date(self.anchor))

    # -- arithmetic ------------------------------------------------------
    def _shape(self):
        """("ap", first_ordinal, step_days) or ("mo", first_month_index, step_months, day)."""
        k = self.kind
        if k == "daily":
            return ("ap", _MIN_ORD, 1)
        if k == "weekly":
            return ("ap", _MIN_ORD + self.weekday, 7)
        if k == "monthly":
            return ("mo", _T_MIN, 1, self.day)
        if k == "yearly":
            return ("mo", _T_MIN + self.month - 1, 12, self.day)
        a = self.anchor
        if self.unit == "days":
            return ("ap", a.toordinal(), self.step)
        if self.unit == "weeks":
            return ("ap", a.toordinal(), 7 * self.step)
        step = self.step * (12 if self.unit == "years" else 1)
        return ("mo", a.year * 12 + a.month - 1, step, a.day)

    def _total(self):
        shape = self._shape()
        if shape[0] == "ap":
            _, f, s = shape
            return 0 if f > _MAX_ORD else (_MAX_ORD - f) // s + 1
        _, t0, step, _ = shape
        return 0 if t0 > _T_MAX else (_T_MAX - t0) // step + 1

    def _count_before(self, o):
        """How many of the schedule's dates have an ordinal below o."""
        o = max(_MIN_ORD, min(o, _MAX_ORD + 1))
        shape = self._shape()
        if shape[0] == "ap":
            _, f, s = shape
            return 0 if o <= f else (o - f + s - 1) // s
        _, t0, step, day = shape
        if o > _MAX_ORD:
            return self._total()
        d = date.fromordinal(o)
        tm = d.year * 12 + d.month - 1
        k = 0 if tm <= t0 else (tm - t0 + step - 1) // step
        if t0 + k * step == tm and self._month_date(tm, day) < d:
            k += 1
        return min(k, self._total())

    @staticmethod
    def _month_date(t, day):
        y, m = divmod(t, 12)
        m += 1
        ld = last_day(y, m)
        return date(y, m, ld if day == 0 else min(day, ld))

    def _nth(self, k):
        shape = self._shape()
        if shape[0] == "ap":
            _, f, s = shape
            return date.fromordinal(f + k * s)
        _, t0, step, day = shape
        return self._month_date(t0 + k * step, day)

    def between(self, start, end):
        _need_date(start, "start")
        _need_date(end, "end")
        if end < start:
            return []
        lo = self._count_before(start.toordinal())
        hi = self._count_before(end.toordinal() + 1)
        return [self._nth(i) for i in range(lo, hi)]


def _need_date(value, what):
    if not is_date(value):
        raise RecurringError("%s must be a date, got '%s'" % (what, value))


def parse_schedule(text):
    if isinstance(text, Schedule):
        raise _bad(text)
    if not isinstance(text, str):
        raise _bad(text)
    words = text.lower().split()
    n = len(words)
    if n == 1 and words[0] == "daily":
        return Schedule("daily")
    if n == 3 and words[0] == "weekly" and words[1] == "on" and words[2] in _WEEKDAYS:
        return Schedule("weekly", weekday=_WEEKDAYS.index(words[2]))
    if n == 3 and words[0] == "monthly" and words[1] == "on":
        if words[2] == "last":
            return Schedule("monthly", day=0)
        if _NUM_RE.fullmatch(words[2]) and 1 <= int(words[2]) <= 31:
            return Schedule("monthly", day=int(words[2]))
    if n == 3 and words[0] == "yearly" and words[1] == "on":
        m = _YMD_RE.fullmatch(words[2])
        if m:
            month, day = int(m.group(1)), int(m.group(2))
            if 1 <= month <= 12 and 1 <= day <= (29 if month == 2 else last_day(2001, month)):
                return Schedule("yearly", month=month, day=day)
    if n == 5 and words[0] == "every" and words[3] == "from" and words[2] in _UNITS:
        if _NUM_RE.fullmatch(words[1]) and int(words[1]) >= 1:
            try:
                anchor = parse_date(words[4])
            except DateError:
                raise _bad(text) from None
            return Schedule("every", step=int(words[1]), unit=_UNITS[words[2]], anchor=anchor)
    raise _bad(text)


def _as_schedule(value):
    if isinstance(value, Schedule):
        return value
    if isinstance(value, str):
        return parse_schedule(value)
    raise RecurringError("schedule must be a Schedule or text, got '%s'" % (value,))


class Recurring:
    def __init__(self, name, schedule, template, start, end=None, count=None):
        if not isinstance(name, str) or not _NAME_RE.fullmatch(name):
            raise RecurringError(
                "invalid name '%s': use letters, digits, '-' and '_', not starting with '-' or '_'" % (name,)
            )
        sched = _as_schedule(schedule)
        if not isinstance(template, Transaction):
            raise RecurringError("template must be a Transaction, got '%s'" % (template,))
        _need_date(start, "start")
        if end is not None:
            _need_date(end, "end")
            if end < start:
                raise RecurringError("end %s is before start %s" % (format_date(end), format_date(start)))
        if count is not None and (not isinstance(count, int) or isinstance(count, bool) or count < 1):
            raise RecurringError("count must be a whole number of at least 1, got '%s'" % (count,))
        self.name = name
        self.schedule = sched
        self.template = template
        self.start = start
        self.end = end
        self.count = count

    def _key(self):
        return (self.name, self.schedule, self.template, self.start, self.end, self.count)

    def __eq__(self, other):
        if not isinstance(other, Recurring):
            return NotImplemented
        return self._key() == other._key()

    __hash__ = None

    def __repr__(self):
        return "Recurring(%r, '%s', start=%s, end=%s, count=%s)" % (
            self.name, self.schedule, self.start, self.end, self.count,
        )

    def _range(self):
        """Index range [i0, i1) of the series in the schedule's own numbering."""
        sched = self.schedule
        i0 = sched._count_before(self.start.toordinal())
        i1 = sched._total()
        if self.end is not None:
            i1 = min(i1, sched._count_before(self.end.toordinal() + 1))
        if self.count is not None:
            i1 = min(i1, i0 + self.count)
        return i0, max(i0, i1)


def _need_recurring(rec):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: '%s'" % (rec,))


def _window(rec, start, end):
    _need_recurring(rec)
    _need_date(start, "start")
    _need_date(end, "end")
    if end < start:
        return range(0)
    i0, i1 = rec._range()
    lo = max(i0, rec.schedule._count_before(start.toordinal()))
    hi = min(i1, rec.schedule._count_before(end.toordinal() + 1))
    return range(lo, hi)


def occurrences(rec, start, end):
    window = _window(rec, start, end)
    return [rec.schedule._nth(i) for i in window]


def next_occurrence(rec, after):
    _need_recurring(rec)
    _need_date(after, "after")
    i0, i1 = rec._range()
    i = max(i0, rec.schedule._count_before(after.toordinal() + 1))
    return rec.schedule._nth(i) if i < i1 else None


def instantiate(rec, on):
    _need_recurring(rec)
    _need_date(on, "date")
    t = rec.template
    tags = tuple(sorted(set(t.tags) | {"recurring"}))
    return Transaction(on, t.payee, t.narration, list(t.postings), tags, t.flag, None)


def expand(recs, start, end):
    if isinstance(recs, (str, bytes)) or not hasattr(recs, "__iter__"):
        raise RecurringError("recs must be a list of Recurring items")
    recs = list(recs)
    _need_date(start, "start")
    _need_date(end, "end")
    found = []
    for pos, rec in enumerate(recs):
        for on in occurrences(rec, start, end):
            found.append((on, rec.name, pos, rec))
    found.sort(key=lambda e: e[:3])
    return [instantiate(rec, on) for on, _, _, rec in found]


def _ordinal(n):
    if 10 <= n % 100 <= 20:
        return "%dth" % n
    return "%d%s" % (n, {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th"))


def describe(schedule):
    if not isinstance(schedule, Schedule):
        raise RecurringError("not a schedule: '%s'" % (schedule,))
    k = schedule.kind
    if k == "daily":
        return "every day"
    if k == "weekly":
        return "every %s" % _WEEKDAY_NAMES[schedule.weekday]
    if k == "monthly":
        if schedule.day == 0:
            return "on the last day of every month"
        return "on the %s of every month" % _ordinal(schedule.day)
    if k == "yearly":
        return "every year on %d %s" % (schedule.day, _MONTH_NAMES[schedule.month - 1])
    if schedule.step == 1:
        return "every %s from %s" % (schedule.unit[:-1], format_date(schedule.anchor))
    return "every %d %s from %s" % (schedule.step, schedule.unit, format_date(schedule.anchor))

"""Strict dates, month arithmetic and periods."""
import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta

from .errors import ParseError


class DateError(ParseError):
    pass


def is_date(x):
    return isinstance(x, date) and not isinstance(x, datetime)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date '%s': expected text" % (text,))
    m = _DATE_RE.fullmatch(text)
    if not m:
        raise DateError("invalid date '%s': expected YYYY-MM-DD" % text)
    try:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise DateError("invalid date '%s': no such day" % text) from None


def format_date(d):
    if not is_date(d):
        raise DateError("not a date: '%s'" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not _is_int(year) or not _is_int(month):
        raise DateError("year and month must be integers")
    if not 1 <= month <= 12 or not 1 <= year <= 9999:
        raise DateError("no such month: %s-%s" % (year, month))
    if month == 12:
        return 31
    return (date(year, month + 1, 1) - timedelta(days=1)).day


def add_months(d, n):
    if not is_date(d):
        raise DateError("not a date: '%s'" % (d,))
    if not _is_int(n):
        raise DateError("months must be an integer, got '%s'" % (n,))
    total = d.year * 12 + (d.month - 1) + n
    y, m = divmod(total, 12)
    m += 1
    if not 1 <= y <= 9999:
        raise DateError("date out of range: %s plus %d months" % (format_date(d), n))
    return date(y, m, min(d.day, last_day(y, m)))


@dataclass(frozen=True)
class Period:
    start: date
    end: date

    def __post_init__(self):
        if not is_date(self.start) or not is_date(self.end):
            raise DateError("period needs two dates, got '%s' and '%s'" % (self.start, self.end))
        if self.end < self.start:
            raise DateError("empty period: %s is before %s" % (format_date(self.end), format_date(self.start)))

    def contains(self, d):
        if not is_date(d):
            raise DateError("not a date: '%s'" % (d,))
        return self.start <= d <= self.end

    @property
    def days(self):
        return (self.end - self.start).days + 1

    def _kind(self):
        s, e = self.start, self.end
        if s.day != 1:
            return None
        if s.month == 1 and e.year == s.year and e.month == 12 and e.day == 31:
            return "year"
        if e.year == s.year and e.month == s.month and e.day == last_day(e.year, e.month):
            return "month"
        if (
            s.month in (1, 4, 7, 10)
            and e.year == s.year
            and e.month == s.month + 2
            and e.day == last_day(e.year, e.month)
        ):
            return "quarter"
        return None

    @property
    def label(self):
        kind = self._kind()
        s = self.start
        if kind == "year":
            return "%04d" % s.year
        if kind == "month":
            return "%04d-%02d" % (s.year, s.month)
        if kind == "quarter":
            return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
        return "%s..%s" % (format_date(self.start), format_date(self.end))

    def __str__(self):
        return self.label

    def next(self):
        kind = self._kind()
        s = self.start
        try:
            if kind == "year":
                return _year(s.year + 1)
            if kind == "month":
                return _month_after(s)
            if kind == "quarter":
                nxt = add_months(s, 3)
                return _span(nxt, _month_of(nxt.year, nxt.month + 2).end)
            ns = self.end + timedelta(days=1)
            return Period(ns, ns + timedelta(days=self.days - 1))
        except OverflowError:
            raise DateError("period after %s is out of range" % self.label) from None

    @staticmethod
    def parse(text):
        return _parse_period(text)


def _span(a, b):
    return Period(a, b)


def _year(y):
    if not 1 <= y <= 9999:
        raise DateError("year %d is out of range" % y)
    return Period(date(y, 1, 1), date(y, 12, 31))


def _month_after(s):
    nxt = add_months(s, 1)
    return Period(nxt, date(nxt.year, nxt.month, last_day(nxt.year, nxt.month)))


def _month_of(y, m):
    return Period(date(y, m, 1), date(y, m, last_day(y, m)))


_YEAR_RE = re.compile(r"([0-9]{4})")
_MONTH_RE = re.compile(r"([0-9]{4})-([0-9]{2})")
_QUARTER_RE = re.compile(r"([0-9]{4})-Q([1-4])")


def _parse_period(text):
    if not isinstance(text, str):
        raise DateError("invalid period '%s': expected text" % (text,))
    try:
        m = _YEAR_RE.fullmatch(text)
        if m:
            return _year(int(m.group(1)))
        m = _MONTH_RE.fullmatch(text)
        if m:
            return _month_of(int(m.group(1)), int(m.group(2)))
        m = _QUARTER_RE.fullmatch(text)
        if m:
            y, q = int(m.group(1)), int(m.group(2))
            first = _month_of(y, 3 * q - 2)
            return Period(first.start, _month_of(y, 3 * q).end)
        parts = text.split("..")
        if len(parts) == 2:
            return Period(parse_date(parts[0]), parse_date(parts[1]))
    except (DateError, ValueError):
        pass
    raise DateError("invalid period '%s'" % text)


_STEPS = ("week", "month", "quarter", "year")


def _containing(d, step):
    if step == "week":
        start = d - timedelta(days=d.weekday())
        try:
            return Period(start, start + timedelta(days=6))
        except OverflowError:
            raise DateError("week of %s passes the last supported day" % format_date(d)) from None
    if step == "month":
        return _month_of(d.year, d.month)
    if step == "quarter":
        q = (d.month - 1) // 3
        return Period(date(d.year, 3 * q + 1, 1), _month_of(d.year, 3 * q + 3).end)
    return _year(d.year)


def periods(start, end, step):
    if not is_date(start) or not is_date(end):
        raise DateError("periods needs two dates, got '%s' and '%s'" % (start, end))
    if not isinstance(step, str) or step not in _STEPS:
        raise DateError("unknown step '%s': expected week, month, quarter or year" % (step,))
    if end < start:
        raise DateError("end %s is before start %s" % (format_date(end), format_date(start)))
    p = _containing(start, step)
    out = [p]
    while p.end < end:
        p = _containing(p.end + timedelta(days=1), step)
        out.append(p)
    return out

"""Reports over a ledger: plain dicts, text tables and CSV."""
from .accounts import ROOT_TYPES
from .currency import currency as _currency
from .dates import Period, format_date, is_date, periods
from .errors import ValidationError
from .export import render_table, to_csv
from .ledger import Ledger
from .money import Money, format_minor, round_div


class ReportError(ValidationError):
    pass


REPORTS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")
STEPS = ("week", "month", "quarter", "year")


# -- helpers --------------------------------------------------------------
def _m(minor, cur):
    return {"amount": format_minor(minor, cur), "currency": cur}


def _mlist(sums):
    return [_m(v, c) for c, v in sorted(sums.items())]


def _need_ledger(ledger):
    if not isinstance(ledger, Ledger):
        raise ReportError("not a ledger: '%s'" % (ledger,))


def _need_date_or_none(as_of):
    if as_of is not None and not is_date(as_of):
        raise ReportError("as_of must be a date or None, got '%s'" % (as_of,))


def _need_period(period):
    if not isinstance(period, Period):
        raise ReportError("period must be a Period, got '%s'" % (period,))


def _kind(account):
    return ROOT_TYPES.get(account.split(":", 1)[0])


def _converter(ledger, convert_to, on):
    if convert_to is None:
        return None
    _currency(convert_to)
    if on is None:
        raise ReportError("converting to %s needs a date: as_of may not be None" % convert_to)

    def convert(minor, cur):
        return ledger.rates.convert(Money(minor, cur), convert_to, on)

    return convert


def _percent(n, d):
    if d == 0:
        return "0.0"
    tenths = round_div(n * 1000, d) if d > 0 else round_div(-n * 1000, -d)
    sign = "-" if tenths < 0 else ""
    return "%s%d.%d" % (sign, abs(tenths) // 10, abs(tenths) % 10)


# -- trial balance --------------------------------------------------------
def trial_balance(ledger, as_of):
    _need_ledger(ledger)
    _need_date_or_none(as_of)
    balances = ledger.balances(as_of)
    accounts = []
    debits, credits = {}, {}
    for account in sorted(balances):
        for cur, minor in sorted(balances[account].items()):
            if minor > 0:
                debit, credit = _m(minor, cur), None
                debits[cur] = debits.get(cur, 0) + minor
                credits.setdefault(cur, 0)
            else:
                debit, credit = None, _m(-minor, cur)
                credits[cur] = credits.get(cur, 0) - minor
                debits.setdefault(cur, 0)
            accounts.append({"account": account, "type": _kind(account), "debit": debit, "credit": credit})
    totals = [
        {
            "currency": cur,
            "debit": _m(debits[cur], cur),
            "credit": _m(credits[cur], cur),
            "balanced": debits[cur] == credits[cur],
        }
        for cur in sorted(debits)
    ]
    return {
        "report": "trial_balance",
        "as_of": None if as_of is None else format_date(as_of),
        "accounts": accounts,
        "totals": totals,
    }


# -- balance sheet --------------------------------------------------------
def _sheet_section(lines, convert, convert_to):
    accounts, totals = [], ({} if convert is None else {convert_to: 0})
    for account, cur, minor in lines:
        if convert is None:
            accounts.append({"account": account, "balance": _m(minor, cur)})
            totals[cur] = totals.get(cur, 0) + minor
        else:
            got = convert(minor, cur)
            accounts.append(
                {"account": account, "balance": _m(got.minor, got.currency), "original": _m(minor, cur)}
            )
            totals[convert_to] += got.minor
    return accounts, totals


def balance_sheet(ledger, as_of, convert_to=None, today=None):
    _need_ledger(ledger)
    _need_date_or_none(as_of)
    convert = _converter(ledger, convert_to, as_of)
    balances = ledger.balances(as_of)
    lines = {"asset": [], "liability": [], "equity": []}
    retained = {}
    for account in sorted(balances):
        kind = _kind(account)
        for cur, minor in sorted(balances[account].items()):
            if kind == "asset":
                lines["asset"].append((account, cur, minor))
            elif kind in ("liability", "equity"):
                lines[kind].append((account, cur, -minor))
            else:
                retained[cur] = retained.get(cur, 0) - minor
    retained = {c: v for c, v in retained.items() if v != 0}

    assets, a_tot = _sheet_section(lines["asset"], convert, convert_to)
    liabilities, l_tot = _sheet_section(lines["liability"], convert, convert_to)
    equity, e_tot = _sheet_section(lines["equity"], convert, convert_to)
    if convert is None:
        retained_list = _mlist(retained)
        for cur, v in retained.items():
            e_tot[cur] = e_tot.get(cur, 0) + v
    elif retained:
        total = sum(convert(v, c).minor for c, v in retained.items())
        retained_list = [_m(total, convert_to)]
        e_tot[convert_to] += total
    else:
        retained_list = []
    currencies = set(a_tot) | set(l_tot) | set(e_tot)
    balanced = all(
        a_tot.get(c, 0) == l_tot.get(c, 0) + e_tot.get(c, 0) for c in currencies
    )
    return {
        "report": "balance_sheet",
        "as_of": None if as_of is None else format_date(as_of),
        "currency": convert_to,
        "assets": {"accounts": assets, "total": _mlist(a_tot)},
        "liabilities": {"accounts": liabilities, "total": _mlist(l_tot)},
        "equity": {"accounts": equity, "retained_earnings": retained_list, "total": _mlist(e_tot)},
        "balanced": balanced,
    }


# -- income statement -----------------------------------------------------
def _statement_section(sums, convert, convert_to):
    rows = []
    totals = {} if convert is None else {convert_to: 0}
    for (account, cur), minor in sorted(sums.items()):
        if minor == 0:
            continue
        if convert is None:
            rows.append((account, cur, minor, None))
            totals[cur] = totals.get(cur, 0) + minor
        else:
            got = convert(minor, cur)
            rows.append((account, convert_to, got.minor, _m(minor, cur)))
            totals[convert_to] += got.minor
    accounts = []
    for account, cur, minor, original in rows:
        line = {"account": account, "amount": _m(minor, cur), "percent": _percent(minor, totals[cur])}
        if original is not None:
            line["original"] = original
        accounts.append(line)
    return accounts, totals


def income_statement(ledger, period, convert_to=None):
    _need_ledger(ledger)
    _need_period(period)
    convert = _converter(ledger, convert_to, period.end)
    income, expenses = {}, {}
    for tx, p in ledger.postings():
        if not period.start <= tx.date <= period.end:
            continue
        kind = _kind(p.account)
        key = (p.account, p.amount.currency)
        if kind == "income":
            income[key] = income.get(key, 0) - p.amount.minor
        elif kind == "expense":
            expenses[key] = expenses.get(key, 0) + p.amount.minor
    inc_lines, inc_tot = _statement_section(income, convert, convert_to)
    exp_lines, exp_tot = _statement_section(expenses, convert, convert_to)
    if convert is None:
        net = {c: inc_tot.get(c, 0) - exp_tot.get(c, 0) for c in set(inc_tot) | set(exp_tot)}
    else:
        net = {convert_to: inc_tot[convert_to] - exp_tot[convert_to]}
    return {
        "report": "income_statement",
        "start": format_date(period.start),
        "end": format_date(period.end),
        "currency": convert_to,
        "income": {"accounts": inc_lines, "total": _mlist(inc_tot)},
        "expenses": {"accounts": exp_lines, "total": _mlist(exp_tot)},
        "net": _mlist(net),
    }


# -- cash flow ------------------------------------------------------------
def cashflow(ledger, period):
    _need_ledger(ledger)
    _need_period(period)
    opening, closing = {}, {}
    contributions = {}
    for tx in ledger.transactions():
        if tx.date > period.end:
            continue
        asset_sum = {}
        for p in tx.postings:
            if _kind(p.account) == "asset":
                cur = p.amount.currency
                asset_sum[cur] = asset_sum.get(cur, 0) + p.amount.minor
                closing[cur] = closing.get(cur, 0) + p.amount.minor
                if tx.date < period.start:
                    opening[cur] = opening.get(cur, 0) + p.amount.minor
                else:
                    opening.setdefault(cur, 0)
        if tx.date < period.start:
            continue
        for p in tx.postings:
            cur = p.amount.currency
            if _kind(p.account) != "asset" and asset_sum.get(cur, 0) != 0:
                key = (p.account, cur)
                contributions[key] = contributions.get(key, 0) - p.amount.minor
    inflows, outflows = [], []
    total_in = {c: 0 for c in closing}
    total_out = {c: 0 for c in closing}
    for (account, cur), minor in sorted(contributions.items()):
        if minor > 0:
            inflows.append({"account": account, "amount": _m(minor, cur)})
            total_in[cur] += minor
        elif minor < 0:
            outflows.append({"account": account, "amount": _m(-minor, cur)})
            total_out[cur] -= minor
    net = {c: total_in[c] - total_out[c] for c in closing}
    return {
        "report": "cashflow",
        "start": format_date(period.start),
        "end": format_date(period.end),
        "opening": _mlist(opening),
        "inflows": inflows,
        "outflows": outflows,
        "total_in": _mlist(total_in),
        "total_out": _mlist(total_out),
        "net": _mlist(net),
        "closing": _mlist(closing),
    }


# -- register -------------------------------------------------------------
def register(ledger, account, period=None, rollup=False):
    _need_ledger(ledger)
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account '%s'" % (account,))
    if period is not None:
        _need_period(period)
    if not isinstance(rollup, bool):
        raise ReportError("rollup must be true or false, got '%s'" % (rollup,))
    prefix = account + ":"
    opening, running = {}, {}
    rows = []
    for tx, p in ledger.postings():
        if p.account != account and not (rollup and p.account.startswith(prefix)):
            continue
        if period is not None and tx.date > period.end:
            continue
        cur, minor = p.amount.currency, p.amount.minor
        running.setdefault(cur, 0)
        opening.setdefault(cur, 0)
        if period is not None and tx.date < period.start:
            opening[cur] += minor
            running[cur] += minor
            continue
        running[cur] += minor
        rows.append(
            {
                "date": format_date(tx.date),
                "id": tx.id,
                "payee": tx.payee,
                "narration": tx.narration,
                "account": p.account,
                "amount": _m(minor, cur),
                "balance": _m(running[cur], cur),
            }
        )
    return {
        "report": "register",
        "account": account,
        "rollup": rollup,
        "start": None if period is None else format_date(period.start),
        "end": None if period is None else format_date(period.end),
        "opening": _mlist(opening),
        "rows": rows,
        "closing": _mlist(running),
    }


# -- net worth ------------------------------------------------------------
def net_worth(ledger, period, step="month"):
    _need_ledger(ledger)
    _need_period(period)
    if not isinstance(step, str) or step not in STEPS:
        raise ReportError("unknown step '%s': expected week, month, quarter or year" % (step,))
    posts = [(tx.date, p) for tx, p in ledger.postings() if _kind(p.account) in ("asset", "liability")]
    assets, liabs = {}, {}
    seen = 0
    points = []
    for span in periods(period.start, period.end, step):
        while seen < len(posts) and posts[seen][0] <= span.end:
            p = posts[seen][1]
            cur, minor = p.amount.currency, p.amount.minor
            assets.setdefault(cur, 0)
            liabs.setdefault(cur, 0)
            if _kind(p.account) == "asset":
                assets[cur] += minor
            else:
                liabs[cur] -= minor
            seen += 1
        points.append(
            {
                "date": format_date(span.end),
                "assets": _mlist(assets),
                "liabilities": _mlist(liabs),
                "net": _mlist({c: assets[c] - liabs[c] for c in assets}),
            }
        )
    return {
        "report": "net_worth",
        "start": format_date(period.start),
        "end": format_date(period.end),
        "step": step,
        "points": points,
    }


# -- text -----------------------------------------------------------------
def _mt(money):
    return "" if money is None else "%s %s" % (money["amount"], money["currency"])


def _join(blocks):
    rows = []
    for block in blocks:
        if not block:
            continue
        if rows:
            rows.append([""] * len(block[0]))
        rows.extend(block)
    return rows


def _titled(title, headers, rows, align):
    return title + "\n\n" + render_table(headers, rows, align)


def _text_trial_balance(r):
    title = "Trial balance" if r["as_of"] is None else "Trial balance as of %s" % r["as_of"]
    rows = [[a["account"], a["type"], _mt(a["debit"]), _mt(a["credit"])] for a in r["accounts"]]
    rows += [["Total", "", _mt(t["debit"]), _mt(t["credit"])] for t in r["totals"]]
    return _titled(title, ["Account", "Type", "Debit", "Credit"], rows, "llrr")


def _text_balance_sheet(r):
    title = "Balance sheet" if r["as_of"] is None else "Balance sheet as of %s" % r["as_of"]
    if r["currency"] is not None:
        title += " (in %s)" % r["currency"]

    def lines(section):
        return [["  " + a["account"], _mt(a["balance"])] for a in section["accounts"]]

    def totals(label, section):
        return [[label, _mt(m)] for m in section["total"]]

    assets, liabilities, equity = r["assets"], r["liabilities"], r["equity"]
    blocks = [
        [["Assets", ""]] + lines(assets) + totals("Total assets", assets),
        [["Liabilities", ""]] + lines(liabilities) + totals("Total liabilities", liabilities),
        [["Equity", ""]]
        + lines(equity)
        + [["  Retained earnings", _mt(m)] for m in equity["retained_earnings"]]
        + totals("Total equity", equity),
    ]
    return _titled(title, ["Account", "Balance"], _join(blocks), "lr")


def _text_income_statement(r):
    title = "Income statement %s to %s" % (r["start"], r["end"])
    if r["currency"] is not None:
        title += " (in %s)" % r["currency"]

    def block(heading, label, section):
        rows = [[heading, "", ""]]
        rows += [["  " + a["account"], _mt(a["amount"]), a["percent"] + "%"] for a in section["accounts"]]
        rows += [[label, _mt(m), ""] for m in section["total"]]
        return rows

    blocks = [
        block("Income", "Total income", r["income"]),
        block("Expenses", "Total expenses", r["expenses"]),
        [["Net income", _mt(m), ""] for m in r["net"]],
    ]
    return _titled(title, ["Account", "Amount", "Percent"], _join(blocks), "lrr")


def _text_cashflow(r):
    title = "Cash flow %s to %s" % (r["start"], r["end"])
    blocks = [
        [["Opening balance", _mt(m)] for m in r["opening"]],
        [["Money in", ""]]
        + [["  " + a["account"], _mt(a["amount"])] for a in r["inflows"]]
        + [["Total money in", _mt(m)] for m in r["total_in"]],
        [["Money out", ""]]
        + [["  " + a["account"], _mt(a["amount"])] for a in r["outflows"]]
        + [["Total money out", _mt(m)] for m in r["total_out"]],
        [["Net change", _mt(m)] for m in r["net"]] + [["Closing balance", _mt(m)] for m in r["closing"]],
    ]
    return _titled(title, ["Account", "Amount"], _join(blocks), "lr")


def _text_net_worth(r):
    title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
    rows = []
    for point in r["points"]:
        if not point["net"]:
            rows.append([point["date"], "", "", ""])
            continue
        by = {k: {m["currency"]: m for m in point[k]} for k in ("assets", "liabilities", "net")}
        for m in point["net"]:
            cur = m["currency"]
            rows.append(
                [point["date"], _mt(by["assets"].get(cur)), _mt(by["liabilities"].get(cur)), _mt(m)]
            )
    return _titled(title, ["Date", "Assets", "Liabilities", "Net"], rows, "lrrr")


def _text_register(r):
    title = "Register %s" % r["account"]
    if r["rollup"]:
        title += " (with sub-accounts)"
    if r["start"] is not None:
        title += " %s to %s" % (r["start"], r["end"])
    rows = [["", "", "Opening balance", "", "", _mt(m)] for m in r["opening"]]
    for row in r["rows"]:
        rows.append(
            [
                row["date"],
                "" if row["id"] is None else row["id"],
                row["payee"],
                row["account"],
                _mt(row["amount"]),
                _mt(row["balance"]),
            ]
        )
    rows += [["", "", "Closing balance", "", "", _mt(m)] for m in r["closing"]]
    return _titled(title, ["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr")


_TEXT = {
    "trial_balance": _text_trial_balance,
    "balance_sheet": _text_balance_sheet,
    "income_statement": _text_income_statement,
    "cashflow": _text_cashflow,
    "register": _text_register,
    "net_worth": _text_net_worth,
}


def _kind_of(report):
    if not isinstance(report, dict) or not isinstance(report.get("report"), str):
        raise ReportError("not a report: '%s'" % (report,))
    kind = report["report"]
    if kind not in REPORTS:
        raise ReportError("unknown report '%s'" % kind)
    return kind


def render_text(report):
    kind = _kind_of(report)
    try:
        return _TEXT[kind](report)
    except (KeyError, TypeError, AttributeError, IndexError, ValueError):
        raise ReportError("malformed %s report" % kind) from None


