def _check_currency(self, p):
    want = self.chart.get(p.account).currency
    if want is not None and p.amount.currency != want:
        raise LedgerError(
            "account %s only holds %s, not %s" % (p.account, want, p.amount.currency)
        )

def _assign_id(self, tx):
    if tx.id is None:
        return self._max_id + 1
    if not _is_int(tx.id) or tx.id < 1:
        raise LedgerError("transaction id must be an integer of at least 1, got '%s'" % (tx.id,))
    if tx.id in self._txs:
        raise LedgerError("transaction %d already exists" % tx.id)
    return tx.id

# -- mutation ---------------------------------------------------------
def add(self, tx):
    if isinstance(tx, Transaction):
        tx_id = self._assign_id(tx)
    else:
        tx_id = None
    stored = self._build(tx, tx_id)
    self._txs[stored.id] = stored
    self._max_id = max(self._max_id, stored.id)
    return stored

def add_many(self, transactions):
    snapshot = (dict(self._txs), self._max_id)
    out = []
    try:
        for tx in transactions:
            out.append(self.add(tx))
    except BaseException:
        self._txs, self._max_id = snapshot
        raise
    return out

def replace(self, id, tx):
    if id not in self._txs:
        raise NotFoundError("no transaction %s" % (id,))
    if not isinstance(tx, Transaction):
        raise LedgerError("not a transaction: '%s'" % (tx,))
    if tx.id is not None and tx.id != id:
        raise LedgerError("transaction id %s does not match %s" % (tx.id, id))
    stored = self._build(tx, id)
    self._txs[id] = stored
    return stored

def remove(self, id):
    if id not in self._txs:
        raise NotFoundError("no transaction %s" % (id,))
    return self._txs.pop(id)

# -- lookup -----------------------------------------------------------
def get(self, id):
    if id not in self._txs:
        raise NotFoundError("no transaction %s" % (id,))
    return self._txs[id]

def transactions(self):
    return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

def postings(self):
    for tx in self.transactions():
        for p in tx.postings:
            yield tx, p

# -- balances ---------------------------------------------------------
def _walk(self, as_of):
    if as_of is not None and not is_date(as_of):
        raise LedgerError("as_of must be a date, got '%s'" % (as_of,))
    for tx, p in self.postings():
        if as_of is None or tx.date <= as_of:
            yield p

@staticmethod
def _clean(acc):
    out = {}
    for a, cur in acc.items():
        cur = {c: v for c, v in cur.items() if v != 0}
        if cur:
            out[a] = cur
    return out

def balances(self, as_of=None):
    acc = defaultdict(lambda: defaultdict(int))
    for p in self._walk(as_of):
        acc[p.account][p.amount.currency] += p.amount.minor
    return self._clean(acc)

def rollup_balances(self, as_of=None):
    acc = defaultdict(lambda: defaultdict(int))
    for p in self._walk(as_of):
        parts = p.account.split(":")
        for i in range(1, len(parts) + 1):
            acc[":".join(parts[:i])][p.amount.currency] += p.amount.minor
    return self._clean(acc)

def balance(self, account, as_of=None, currency=None, rollup=True):
    if not self.chart.exists(account):
        raise NotFoundError("no such account '%s'" % (account,))
    sums = defaultdict(int)
    for p in self._walk(as_of):
        if p.account == account or (rollup and p.account.startswith(account + ":")):
            sums[p.amount.currency] += p.amount.minor
    if currency is not None:
        return Money(sums.get(currency, 0), currency)
    return {c: Money(v, c) for c, v in sorted(sums.items()) if v != 0}

"""CSV and JSON export of transactions, and fixed-width text tables."""
import json

from .dates import format_date, parse_date
from .errors import ParseError, ValidationError
from .model import Posting, Transaction
from .money import Money


class ExportError(ValidationError):
    pass


CSV_HEADER = ("id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note")


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


# -- CSV ------------------------------------------------------------------
def _csv_field(value):
    text = "" if value is None else str(value)
    if any(ch in text for ch in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def _csv_record(cells):
    return ",".join(_csv_field(c) for c in cells) + "\n"


def to_csv(headers, rows):
    out = [_csv_record(headers)]
    for row in rows:
        out.append(_csv_record(row))
    return "".join(out)


def _tags(tx):
    return sorted(set(tx.tags))


def transactions_to_csv(txs):
    out = [_csv_record(CSV_HEADER)]
    for tx in txs:
        head = [
            "" if tx.id is None else str(tx.id),
            format_date(tx.date),
            tx.flag,
            tx.payee,
            tx.narration,
            ";".join(_tags(tx)),
        ]
        if not tx.postings:
            out.append(_csv_record(head + ["", "", "", ""]))
            continue
        for p in tx.postings:
            if p.amount is None:
                amount, cur = "", ""
            else:
                amount, cur = p.amount.amount_str(), p.amount.currency
            out.append(_csv_record(head + [p.account, amount, cur, p.note]))
    return "".join(out)


# -- JSON -----------------------------------------------------------------
def to_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def money_to_dict(money):
    if money is None:
        return None
    if not isinstance(money, Money):
        raise ExportError("not an amount of money: '%s'" % (money,))
    return {"amount": money.amount_str(), "currency": money.currency}


def transaction_to_dict(tx):
    return {
        "id": tx.id,
        "date": format_date(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": _tags(tx),
        "postings": [
            {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
            for p in tx.postings
        ],
    }


def transactions_to_json(txs):
    return to_json([transaction_to_dict(tx) for tx in txs])


_TX_KEYS = ("id", "date", "flag", "payee", "narration", "tags", "postings")
_POSTING_KEYS = ("account", "amount", "note")


def _unknown_key(obj, known, where):
    for key in obj:
        if key not in known:
            raise ExportError("%s: unknown key '%s'" % (where, key))


def _read_money(obj, where):
    if obj is None:
        return None
    if not isinstance(obj, dict):
        raise ExportError("%s: amount must be null or an object with amount and currency" % where)
    if set(obj) != {"amount", "currency"}:
        raise ExportError("%s: amount must have exactly the keys amount and currency" % where)
    text, cur = obj["amount"], obj["currency"]
    if not isinstance(text, str) or not isinstance(cur, str):
        raise ExportError("%s: amount and currency must be text" % where)
    try:
        return Money.of(text, cur)
    except ValidationError as exc:
        raise ExportError("%s: invalid amount: %s" % (where, exc.message)) from None


def _read_posting(obj, where):
    if not isinstance(obj, dict):
        raise ExportError("%s: not an object" % where)
    _unknown_key(obj, _POSTING_KEYS, where)
    if "account" not in obj:
        raise ExportError("%s: missing 'account'" % where)
    account = obj["account"]
    if not isinstance(account, str):
        raise ExportError("%s: account must be text" % where)
    amount = _read_money(obj.get("amount"), where)
    note = obj.get("note", "")
    if not isinstance(note, str):
        raise ExportError("%s: note must be text" % where)
    return Posting(account, amount, note)


def _read_transaction(obj, where):
    if not isinstance(obj, dict):
        raise ExportError("%s: not an object" % where)
    _unknown_key(obj, _TX_KEYS, where)
    for key in ("date", "payee", "postings"):
        if key not in obj:
            raise ExportError("%s: missing '%s'" % (where, key))
    raw_date = obj["date"]
    if not isinstance(raw_date, str):
        raise ExportError("%s: date must be text in the form YYYY-MM-DD" % where)
    try:
        day = parse_date(raw_date)
    except ParseError:
        raise ExportError("%s: invalid date '%s'" % (where, raw_date)) from None
    tx_id = obj.get("id")
    if tx_id is not None and (not _is_int(tx_id) or tx_id < 1):
        raise ExportError("%s: id must be null or a whole number of at least 1, got '%s'" % (where, tx_id))
    flag = obj.get("flag", "*")
    if not isinstance(flag, str) or flag not in ("*", "!"):
        raise ExportError("%s: flag must be '*' or '!', got '%s'" % (where, flag))
    payee = obj["payee"]
    if not isinstance(payee, str):
        raise ExportError("%s: payee must be text" % where)
    narration = obj.get("narration", "")
    if not isinstance(narration, str):
        raise ExportError("%s: narration must be text" % where)
    tags = obj.get("tags", [])
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        raise ExportError("%s: tags must be a list of text" % where)
    raw_postings = obj["postings"]
    if not isinstance(raw_postings, list):
        raise ExportError("%s: postings must be a list" % where)
    postings = [
        _read_posting(p, "%s posting %d" % (where, i)) for i, p in enumerate(raw_postings, 1)
    ]
    return Transaction(day, payee, narration, postings, tuple(sorted(set(tags))), flag, tx_id)


def transactions_from_json(text):
    if not isinstance(text, str):
        raise ExportError("not JSON: expected text")
    try:
        data = json.loads(text)
    except (ValueError, RecursionError) as exc:
        raise ExportError("not JSON: %s" % exc) from None
    if not isinstance(data, list):
        raise ExportError("expected a JSON array of transactions")
    return [_read_transaction(item, "transaction %d" % i) for i, item in enumerate(data, 1)]


# -- tables ---------------------------------------------------------------
def _cell(value):
    text = "" if value is None else str(value)
    if "\t" in text or "\r" in text or "\n" in text:
        text = text.replace("\t", " ").replace("\r", " ").replace("\n", " ")
    return text


def _alignment(align, count):
    if align is None:
        return ["l"] * count
    if not isinstance(align, (str, list, tuple)):
        raise ExportError("align must be None, a string or a list of 'l' and 'r'")
    letters = list(align)
    for letter in letters:
        if not isinstance(letter, str) or letter not in ("l", "r"):
            raise ExportError("invalid alignment '%s': use 'l' or 'r'" % (letter,))
    if len(letters) != count:
        raise ExportError("alignment has %d letters for %d columns" % (len(letters), count))
    return letters


def render_table(headers, rows, align=None):
    try:
        titles = [_cell(h) for h in headers]
    except TypeError:
        raise ExportError("headers must be an iterable of cells") from None
    if not titles:
        return ""
    count = len(titles)
    letters = _alignment(align, count)
    try:
        body = []
        for number, row in enumerate(rows, 1):
            try:
                cells = [_cell(c) for c in row]
            except TypeError:
                raise ExportError("row %d is not a sequence of cells" % number) from None
            if len(cells) != count:
                raise ExportError("row %d has %d cells for %d columns" % (number, len(cells), count))
            body.append(cells)
    except TypeError:
        raise ExportError("rows must be an iterable of rows") from None
    widths = [len(t) for t in titles]
    for cells in body:
        for i, c in enumerate(cells):
            if len(c) > widths[i]:
                widths[i] = len(c)

    def line(cells):
        parts = [
            c.ljust(w) if a == "l" else c.rjust(w) for c, w, a in zip(cells, widths, letters)
        ]
        return "  ".join(parts).rstrip(" ") + "\n"

    out = [line(titles), "  ".join("-" * w for w in widths) + "\n"]
    out.extend(line(cells) for cells in body)
    return "".join(out)

"""The book file: one SQLite database with numbered schema versions."""
import contextlib
import functools
import json
import os
import re
import sqlite3
import threading
from collections import Counter
from dataclasses import dataclass, field, replace
from datetime import timedelta

from .accounts import ROOT_TYPES, TYPES, Chart
from .currency import CURRENCIES, RateTable
from .dates import format_date, is_date, parse_date
from .errors import ConflictError, NotFoundError, TallybookError, ValidationError
from .ledger import Ledger, LedgerError
from .model import Account, Posting, Transaction
from .money import Money, format_minor

LATEST_VERSION = 4
BUSY_TIMEOUT = 5.0

_INT_MIN = -(2 ** 63)
_INT_MAX = 2 ** 63 - 1
_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_NAME_CHARS_RE = re.compile(r"[A-Za-z0-9_-]+")
_CURRENCY_RE = re.compile(r"[A-Za-z]{3}")
_PROFILE_PREFIX = "profile."

_STEP1 = [
    "CREATE TABLE accounts (path TEXT PRIMARY KEY, type TEXT NOT NULL, currency TEXT, opened TEXT,"
    " note TEXT NOT NULL DEFAULT '')",
    "CREATE TABLE transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL,"
    " payee TEXT NOT NULL, narration TEXT NOT NULL DEFAULT '', cleared INTEGER NOT NULL DEFAULT 1)",
    "CREATE TABLE postings (id INTEGER PRIMARY KEY AUTOINCREMENT,"
    " tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,"
    " seq INTEGER NOT NULL, account TEXT NOT NULL REFERENCES accounts(path),"
    " minor INTEGER NOT NULL, currency TEXT NOT NULL)",
    "CREATE INDEX transactions_date_id ON transactions (date, id)",
    "CREATE INDEX postings_tx_seq ON postings (tx_id, seq)",
]
_STEP2 = [
    "CREATE TABLE tags (tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,"
    " tag TEXT NOT NULL, PRIMARY KEY (tx_id, tag))",
    "ALTER TABLE transactions ADD COLUMN flag TEXT NOT NULL DEFAULT '*'",
    "ALTER TABLE postings ADD COLUMN note TEXT NOT NULL DEFAULT ''",
]
_STEP3 = [
    "CREATE TABLE rates (src TEXT NOT NULL, dst TEXT NOT NULL, on_date TEXT NOT NULL,"
    " rate_text TEXT NOT NULL, PRIMARY KEY (src, dst, on_date))",
    "ALTER TABLE accounts ADD COLUMN closed TEXT",
]
_STEP4 = [
    "CREATE TABLE budgets (pattern TEXT NOT NULL, period_kind TEXT NOT NULL, minor INTEGER NOT NULL,"
    " currency TEXT NOT NULL, start_date TEXT NOT NULL, PRIMARY KEY (pattern, period_kind))",
    "CREATE TABLE recurring (name TEXT PRIMARY KEY, schedule TEXT NOT NULL, template TEXT NOT NULL,"
    " start_date TEXT NOT NULL, end_date TEXT, max_count INTEGER, materialized_through TEXT)",
    "CREATE TABLE rules (id INTEGER PRIMARY KEY CHECK (id = 1), body TEXT NOT NULL)",
    "CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
    "CREATE TABLE import_keys (key TEXT PRIMARY KEY,"
    " tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE)",
]


class _StepFailed(Exception):
    pass


def _run_all(conn, statements):
    for sql in statements:
        conn.execute(sql)


def _step1(conn):
    _run_all(conn, _STEP1)


def _step2(conn):
    bad = conn.execute(
        "SELECT id, cleared FROM transactions WHERE cleared IS NULL OR cleared NOT IN (0, 1)"
        " ORDER BY id LIMIT 1"
    ).fetchone()
    if bad is not None:
        raise _StepFailed("transaction %s has cleared value %r, expected 0 or 1" % (bad[0], bad[1]))
    _run_all(conn, _STEP2)
    conn.execute("UPDATE transactions SET flag = CASE cleared WHEN 1 THEN '*' ELSE '!' END")


def _clean_currency(value, what, allow_empty):
    if not isinstance(value, str):
        raise _StepFailed("%s has an invalid currency %r" % (what, value))
    cleaned = value.strip()
    if not cleaned:
        if allow_empty:
            return None
        raise _StepFailed("%s has an empty currency" % what)
    if not _CURRENCY_RE.fullmatch(cleaned):
        raise _StepFailed("%s has an invalid currency '%s'" % (what, value))
    return cleaned.upper()


def _step3(conn):
    _run_all(conn, _STEP3)
    for path, cur in conn.execute("SELECT path, currency FROM accounts WHERE currency IS NOT NULL").fetchall():
        cleaned = _clean_currency(cur, "account %s" % path, True)
        if cleaned != cur:
            conn.execute("UPDATE accounts SET currency = ? WHERE path = ?", (cleaned, path))
    for (cur,) in conn.execute("SELECT DISTINCT currency FROM postings").fetchall():
        cleaned = _clean_currency(cur, "a posting", False)
        if cleaned != cur:
            conn.execute("UPDATE postings SET currency = ? WHERE currency = ?", (cleaned, cur))


def _step4(conn):
    _run_all(conn, _STEP4)


_STEPS = {1: _step1, 2: _step2, 3: _step3, 4: _step4}


@dataclass
class BulkAdd:
    added: list = field(default_factory=list)
    skipped: list = field(default_factory=list)


@dataclass
class ImportOutcome:
    added: list = field(default_factory=list)
    duplicates: list = field(default_factory=list)
    errors: list = field(default_factory=list)


def _db_error(exc):
    text = str(exc)
    low = text.lower()
    if "locked" in low or "busy" in low:
        return ConflictError("database is locked: another process is writing to the book")
    return ConflictError("database error: %s" % text)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _need_text(value, what):
    if not isinstance(value, str):
        raise ValidationError("%s must be text, got '%s'" % (what, value))
    return value


def _fit(value, what):
    if not _INT_MIN <= value <= _INT_MAX:
        raise ValidationError("%s is too large to store in a book" % what)


def _parse_stored_date(text, what):
    try:
        return parse_date(text)
    except TallybookError:
        raise ConflictError("the book holds an invalid date '%s' (%s)" % (text, what)) from None


def _guard(fn):
    @functools.wraps(fn)
    def wrapper(self, *args, **kwargs):
        with self._lock:
            self._check_usable()
            try:
                return fn(self, *args, **kwargs)
            except sqlite3.Error as exc:
                raise _db_error(exc) from None
            except OverflowError:
                raise ValidationError("a number is too large to store in a book") from None
            except UnicodeEncodeError:
                raise ValidationError("text cannot be stored in a book (invalid characters)") from None

    return wrapper


def _import_key_base(tx):
    first = tx.postings[0]
    return "%s|%s|%s|%d %s" % (
        format_date(tx.date), tx.payee, first.account, first.amount.minor, first.amount.currency
    )


class Store:
    def __init__(self, path, fspath, conn):
        self.path = path
        self._fspath = fspath
        self._conn = conn
        self._lock = threading.RLock()
        self._closed = False
        self._in_tx = False
        self._version = conn.execute("PRAGMA user_version").fetchone()[0]

    # -- opening ---------------------------------------------------------
    @classmethod
    def open(cls, path, create=False):
        try:
            fspath = os.fspath(path)
        except TypeError:
            raise ValidationError("path must be text or a path object, got '%s'" % (path,)) from None
        if isinstance(fspath, bytes):
            fspath = os.fsdecode(fspath)
        if not fspath:
            raise NotFoundError("no such book file ''")
        if os.path.isdir(fspath):
            raise ConflictError("'%s' is a directory, not a book" % fspath)
        existed = os.path.exists(fspath)
        if not existed:
            if not create:
                raise NotFoundError("no such book file '%s'" % fspath)
            parent = os.path.dirname(os.path.abspath(fspath))
            if not os.path.isdir(parent):
                raise NotFoundError("the directory for '%s' does not exist" % fspath)
        try:
            conn = sqlite3.connect(
                fspath, timeout=BUSY_TIMEOUT, isolation_level=None, check_same_thread=False
            )
        except sqlite3.Error as exc:
            raise ConflictError("cannot open '%s': %s" % (fspath, exc)) from None
        try:
            conn.execute("PRAGMA foreign_keys = ON")
            version = conn.execute("PRAGMA user_version").fetchone()[0]
            tables = conn.execute("SELECT count(*) FROM sqlite_master").fetchone()[0]
        except sqlite3.Error as exc:
            conn.close()
            if not existed:
                cls._discard(fspath)
            raise ConflictError("'%s' is not a tallybook book: %s" % (fspath, exc)) from None
        if version == 0 and tables > 0:
            conn.close()
            raise ConflictError("'%s' is not a tallybook book: it has tables but no version" % fspath)
        if version > LATEST_VERSION:
            conn.close()
            raise ConflictError(
                "'%s' is at version %d, newer than this tool (version %d)" % (fspath, version, LATEST_VERSION)
            )
        store = cls(path, fspath, conn)
        if version == 0 and create:
            try:
                store.migrate()
            except BaseException:
                store.close()
                if not existed:
                    cls._discard(fspath)
                raise
        return store

    @staticmethod
    def _discard(fspath):
        for suffix in ("", "-journal"):
            with contextlib.suppress(OSError):
                os.unlink(fspath + suffix)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def close(self):
        with self._lock:
            if self._closed:
                return
            self._closed = True
            with contextlib.suppress(sqlite3.Error):
                self._conn.close()

    def _check_usable(self):
        if self._closed:
            raise ConflictError("the book is closed")
        if self._version != LATEST_VERSION:
            self._version = self._read_version()
        if self._version != LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % self._version)

    def _read_version(self):
        try:
            return self._conn.execute("PRAGMA user_version").fetchone()[0]
        except sqlite3.Error as exc:
            raise _db_error(exc) from None

    @property
    def version(self):
        with self._lock:
            if self._closed:
                raise ConflictError("the book is closed")
            if self._version != LATEST_VERSION:
                self._version = self._read_version()
            return self._version

    # -- transactions ----------------------------------------------------
    @contextlib.contextmanager
    def _txn(self, write):
        if self._in_tx:
            yield
            return
        self._conn.execute("BEGIN IMMEDIATE" if write else "BEGIN")
        self._in_tx = True
        try:
            yield
            self._conn.execute("COMMIT")
        except BaseException:
            with contextlib.suppress(sqlite3.Error):
                self._conn.execute("ROLLBACK")
            raise
        finally:
            self._in_tx = False

    def migrate(self):
        with self._lock:
            if self._closed:
                raise ConflictError("the book is closed")
            try:
                current = self._read_version()
                applied = []
                for n in range(current + 1, LATEST_VERSION + 1):
                    try:
                        with self._txn(True):
                            _STEPS[n](self._conn)
                            self._conn.execute("PRAGMA user_version = %d" % n)
                    except _StepFailed as exc:
                        raise ConflictError("migration to version %d failed: %s" % (n, exc)) from None
                    except sqlite3.Error as exc:
                        raise ConflictError("migration to version %d failed: %s" % (n, exc)) from None
                    self._version = n
                    applied.append(n)
                return applied
            finally:
                self._version = self._read_version()

    # -- accounts --------------------------------------------------------
    def _load_chart(self):
        chart = Chart()
        paths = set()
        rows = self._conn.execute(
            "SELECT path, currency, opened, closed, note FROM accounts ORDER BY path"
        ).fetchall()
        for path, cur, opened, closed, note in rows:
            cur = cur or None
            opened_d = _parse_stored_date(opened, "account %s" % path) if opened else None
            known = cur if cur in CURRENCIES else None
            try:
                acct = chart.add(path, None, known, opened_d, note if isinstance(note, str) else "")
            except TallybookError as exc:
                raise ConflictError("the book holds an invalid account '%s': %s" % (path, exc.message)) from None
            acct.currency = cur
            if closed:
                acct.closed = _parse_stored_date(closed, "account %s" % path)
            paths.add(path)
        return chart, paths

    def _stored_account(self, chart, paths, path):
        if not isinstance(path, str) or path not in paths:
            raise NotFoundError("no such account '%s'" % (path,))
        return chart.get(path)

    @_guard
    def add_account(self, path, type=None, currency=None, opened=None, note=""):
        with self._txn(True):
            chart, _ = self._load_chart()
            acct = chart.add(path, type, currency, opened, note)
            self._conn.execute(
                "INSERT INTO accounts (path, type, currency, opened, note) VALUES (?, ?, ?, ?, ?)",
                (acct.path, acct.type, acct.currency, format_date(opened) if opened else None, acct.note),
            )
            return acct

    @_guard
    def get_account(self, path):
        with self._txn(False):
            chart, paths = self._load_chart()
            return self._stored_account(chart, paths, path)

    @_guard
    def accounts(self, type=None, under=None, currency=None, include_closed=True):
        with self._txn(False):
            return self._accounts(type, under, currency, include_closed)

    def _accounts(self, type, under, currency, include_closed):
        if type is not None and (not isinstance(type, str) or type not in TYPES):
            raise ValidationError("unknown account type '%s'" % (type,))
        if under is not None:
            _need_text(under, "under")
        if currency is not None:
            _need_text(currency, "currency")
        chart, paths = self._load_chart()
        out = []
        for path in sorted(paths):
            acct = chart.get(path)
            if type is not None and acct.type != type:
                continue
            if under is not None and not (path == under or path.startswith(under + ":")):
                continue
            if currency is not None and acct.currency != currency:
                continue
            if not include_closed and acct.closed is not None:
                continue
            out.append(acct)
        return out

    @_guard
    def count_accounts(self, type=None, under=None, currency=None, include_closed=True):
        with self._txn(False):
            return len(self._accounts(type, under, currency, include_closed))

    @_guard
    def chart(self):
        with self._txn(False):
            return self._load_chart()[0]

    @_guard
    def close_account(self, path, on):
        with self._txn(True):
            chart, paths = self._load_chart()
            self._stored_account(chart, paths, path)
            acct = chart.close(path, on)
            latest = self._conn.execute(
                "SELECT max(t.date) FROM postings p JOIN transactions t ON t.id = p.tx_id WHERE p.account = ?",
                (path,),
            ).fetchone()[0]
            if latest is not None and latest > format_date(on):
                raise ConflictError(
                    "cannot close account %s on %s: it has a posting on %s" % (path, format_date(on), latest)
                )
            self._conn.execute("UPDATE accounts SET closed = ? WHERE path = ?", (format_date(on), path))
            return acct

    @_guard
    def set_account_note(self, path, note):
        _need_text(note, "note")
        with self._txn(True):
            chart, paths = self._load_chart()
            acct = self._stored_account(chart, paths, path)
            self._conn.execute("UPDATE accounts SET note = ? WHERE path = ?", (note, path))
            acct.note = note
            return acct

    @_guard
    def delete_account(self, path):
        with self._txn(True):
            _, paths = self._load_chart()
            if not isinstance(path, str) or path not in paths:
                raise NotFoundError("no such account '%s'" % (path,))
            used = self._conn.execute("SELECT count(*) FROM postings WHERE account = ?", (path,)).fetchone()[0]
            if used:
                raise ConflictError("account %s cannot be deleted: %d posting(s) use it" % (path, used))
            self._conn.execute("DELETE FROM accounts WHERE path = ?", (path,))

    # -- transactions ----------------------------------------------------
    def _load(self, cond="", params=(), limit=None, offset=0):
        lim = -1 if limit is None else min(limit, _INT_MAX)
        off = min(offset, _INT_MAX)
        sub = "SELECT id FROM transactions %s ORDER BY date, id LIMIT ? OFFSET ?" % cond
        args = tuple(params) + (lim, off)
        rows = self._conn.execute(
            "SELECT id, date, payee, narration, flag FROM transactions %s ORDER BY date, id LIMIT ? OFFSET ?" % cond,
            args,
        ).fetchall()
        postings = {}
        for tx_id, account, minor, cur, note in self._conn.execute(
            "SELECT tx_id, account, minor, currency, note FROM postings WHERE tx_id IN (%s) ORDER BY tx_id, seq" % sub,
            args,
        ):
            try:
                amount = Money(minor, cur)
            except TallybookError as exc:
                raise ConflictError("transaction %s has an invalid amount: %s" % (tx_id, exc.message)) from None
            postings.setdefault(tx_id, []).append(Posting(account, amount, note))
        tags = {}
        for tx_id, tag in self._conn.execute(
            "SELECT tx_id, tag FROM tags WHERE tx_id IN (%s) ORDER BY tx_id, tag" % sub, args
        ):
            tags.setdefault(tx_id, []).append(tag)
        out = []
        for tx_id, day, payee, narration, flag in rows:
            out.append(
                Transaction(
                    _parse_stored_date(day, "transaction %s" % tx_id),
                    payee,
                    narration,
                    postings.get(tx_id, []),
                    tuple(tags.get(tx_id, ())),
                    flag,
                    tx_id,
                )
            )
        return out

    def _validated(self, led, paths, tx):
        if isinstance(tx, Transaction):
            tx = replace(tx, id=None)
        try:
            stored = led.add(tx)
        except TallybookError:
            raise
        except Exception as exc:
            raise LedgerError("invalid transaction: %s" % exc) from None
        led.remove(stored.id)
        for p in stored.postings:
            if p.account not in paths:
                raise LedgerError("unknown account '%s'" % p.account)
            _fit(p.amount.minor, "the amount of a posting to %s" % p.account)
        return stored

    def _insert(self, tx):
        conn = self._conn
        cur = conn.execute(
            "INSERT INTO transactions (date, payee, narration, cleared, flag) VALUES (?, ?, ?, ?, ?)",
            (format_date(tx.date), tx.payee, tx.narration, 1 if tx.flag == "*" else 0, tx.flag),
        )
        tx_id = cur.lastrowid
        for seq, p in enumerate(tx.postings):
            conn.execute(
                "INSERT INTO postings (tx_id, seq, account, minor, currency, note) VALUES (?, ?, ?, ?, ?, ?)",
                (tx_id, seq, p.account, p.amount.minor, p.amount.currency, p.note),
            )
        for tag in tx.tags:
            conn.execute("INSERT INTO tags (tx_id, tag) VALUES (?, ?)", (tx_id, tag))
        return replace(tx, id=tx_id)

    def _ledger_for_adding(self):
        chart, paths = self._load_chart()
        return Ledger(chart), paths

    @_guard
    def add_transaction(self, tx):
        with self._txn(True):
            led, paths = self._ledger_for_adding()
            return self._insert(self._validated(led, paths, tx))

    @_guard
    def add_transactions(self, txs, keys=None):
        try:
            tx_list = list(txs)
        except TypeError:
            raise ValidationError("transactions must be a list") from None
        key_list = None
        if keys is not None:
            try:
                key_list = list(keys)
            except TypeError:
                raise ValidationError("keys must be a list of text") from None
            if len(key_list) != len(tx_list):
                raise ValidationError("keys must have one entry per transaction")
            for k in key_list:
                _need_text(k, "an import key")
        result = BulkAdd()
        with self._txn(True):
            led, paths = self._ledger_for_adding()
            seen = set()
            for i, tx in enumerate(tx_list):
                try:
                    if key_list is not None:
                        key = key_list[i]
                        if key in seen or self._has_key(key):
                            result.skipped.append(i)
                            continue
                    stored = self._insert(self._validated(led, paths, tx))
                    if key_list is not None:
                        self._conn.execute(
                            "INSERT INTO import_keys (key, tx_id) VALUES (?, ?)", (key, stored.id)
                        )
                        seen.add(key)
                except TallybookError as exc:
                    exc.detail["index"] = i
                    raise
                result.added.append(stored)
        return result

    def _has_key(self, key):
        return self._conn.execute("SELECT 1 FROM import_keys WHERE key = ?", (key,)).fetchone() is not None

    @_guard
    def has_import_key(self, key):
        if not isinstance(key, str):
            return False
        with self._txn(False):
            return self._has_key(key)

    @staticmethod
    def _check_paging(limit, offset):
        if limit is not None and (not _is_int(limit) or limit < 0):
            raise ValidationError("limit must be a whole number of at least 0, got '%s'" % (limit,))
